var old = document.querySelectorAll('[data-robot-editor]');for (var i = 0; i < old.length; i++) { old[i].removeAttribute('data-robot-editor'); }var els = document.querySelectorAll('textarea, [contenteditable="true"], [contenteditable=""], [role="textbox"]');var best = null;var bestArea = 0;for (var j = 0; j < els.length; j++) { var r = els[j].getBoundingClientRect(); var a = r.width * r.height; if (a > bestArea) { best = els[j]; bestArea = a; } }if (!best) { return 'none'; }best.setAttribute('data-robot-editor', '1');return best.tagName + ' class=' + best.className;
